j:jelly.g:evaluate:
		function toInt(value) {
			var parsedValue = parseInt(value, 10);
			if (!isNaN(parsedValue))
				return parsedValue;
			return 0;
		};

        var is_doctype = jelly.jvar_cxs_doctype;
        var index = jelly.jvar_cxs_index;

        var docIdArray = jelly.jvar_cxs_result.id.split(":");
        var recordId = docIdArray[1];

        var title = jelly.jvar_cxs_result.title;
        title = GlideStringUtil.escapeHTML(title);
        var snippet = jelly.jvar_cxs_result.snippet;
        var itemLink = jelly.jvar_cxs_result.link + "${AMP}sysparm_stack=no${AMP}sysparm_context=popup${AMP}sysparm_no_create=true${AMP}sysparm_no_update=true${AMP}sysparm_no_info=true${AMP}sysparm_no_history=true${AMP}sysparm_no_suggest=true${AMP}sysparm_no_create_incident=true${AMP}sysparm_no_rating=true";
        var knowledgeBase = GlideStringUtil.escapeHTML(jelly.jvar_cxs_result.meta.knowledgeBase);
        var rating = toInt(jelly.jvar_cxs_result.meta.rating);
        var viewCount = toInt(jelly.jvar_cxs_result.meta.viewCount);
        var number = GlideStringUtil.escapeHTML(jelly.jvar_cxs_result.meta.number);
        var author = GlideStringUtil.escapeHTML(jelly.jvar_cxs_result.meta.author);
        var published = GlideStringUtil.escapeHTML(jelly.jvar_cxs_result.meta.published);
        var score = parseInt(jelly.jvar_cxs_result.meta.score, 10).toString();
        var publication = jelly.jvar_cxs_result.meta.publication;
        var publication_style = JSUtil.nil(publication) ? "display:none" : "";
        var category = jelly.jvar_cxs_result.meta.category;
        var dir = GlideI18NStyle.getDirection();
        var catDelimiter = (dir == 'ltr') ? " > " : " < ";
        var categoryStyle = 'display:none';
        if(!JSUtil.nil(jelly.jvar_cxs_result.meta.parentCategories)) {
            categoryStyle = '';
            category = jelly.jvar_cxs_result.meta.parentCategories.reverse().join(catDelimiter);
        }
		category = GlideStringUtil.escapeHTML(category);

        var tag = jelly.jvar_cxs_result.tag;
        var tag_style = JSUtil.nil(tag) ? "display:none" : '';
        var pinned_class = (jelly.jvar_cxs_result.meta.source == "pinned" ? "pinned" : "");
        var pinnedStyle = (jelly.jvar_cxs_result.meta.source == "pinned" ? "" : "display:none");

        var thisHelpedActionLabel = (jelly.jvar_cxs_result.searchResultActions && jelly.jvar_cxs_result.searchResultActions.this_helped) ? JSON.parse(jelly.jvar_cxs_result.searchResultActions.this_helped).actionLabel : '';
        var thisHelpedActionValue = (jelly.jvar_cxs_result.searchResultActions && jelly.jvar_cxs_result.searchResultActions.this_helped) ? JSON.parse(jelly.jvar_cxs_result.searchResultActions.this_helped).actionValue : '';
        var dataType = jelly.jvar_cxs_result.meta.attachmentType;

        if (jelly.jvar_cxs_result.meta.direct)
            itemLink += jelly.AMP + "view=true";

        var lastModified = jelly.jvar_cxs_result.meta.modified;
        if (lastModified){
            var gdt = new GlideDateTime();
            gdt.setValue(lastModified);
            lastModified = gdt.getDate().getDisplayValue();
        }

        var show = {
            "knowledgeBase": (gs.getProperty("glide.knowman.search.show_knowledgebase", "true") == "true" ? true : false),
            "rating": (gs.getProperty("glide.knowman.search.show_rating", "true") == "true" ? true : false),
            "viewCount": (gs.getProperty("glide.knowman.search.show_view_count", "true") == "true" ? true : false),
            "category": (gs.getProperty("glide.knowman.search.show_category", "true") == "true" ? true : false),
            "number": (gs.getProperty("glide.knowman.search.show_article_number", "true") == "true" ? true : false),
            "author": (gs.getProperty("glide.knowman.search.show_author", "true") == "true" ? true : false),
            "published": (gs.getProperty("glide.knowman.search.show_published", "true") == "true" ? true : false),
            "relevance": (gs.getProperty("glide.knowman.search.show_relevancy", "true") == "true" ? true : false),
            "lastModified": (gs.getProperty("glide.knowman.search.show_last_modified", "true") == "true" ? true : false)
        };

        if(JSUtil.nil(lastModified))
            show.lastModified = false;

		var ratingCounter = 0;
		var ratingDesc = "";

		if(JSUtil.nil(rating))
			rating = 0;

		rating = Math.round(rating);
		if(rating > 0)
			ratingDesc = gs.getMessage("{0} star rating", (rating + ""));
		else
			ratingDesc = gs.getMessage("No rating");
		if(JSUtil.nil(viewCount))
			show.viewCount = false;
		else {
			if(viewCount == 0)
				show.viewCount = false;
			else {
				if(viewCount == 1)
					strViewCount = gs.getMessage("{0} View", (viewCount + ""));
				else
					strViewCount = gs.getMessage("{0} Views", (viewCount + ""));
			}
		}
